mapper.insert:
INSERT INTO agent.mining_agent_conversation (
    conversation_id, user_id, topic, status, start_time, end_time, last_msg_time, is_deleted
) VALUES (
    #{conversationId}, #{userId}, #{topic}, #{status}, #{startTime}, #{endTime}, #{lastMsgTime}, #{isDeleted}
)

mapper.select:
SELECT conversation_id, user_id, topic, status, start_time, end_time, last_msg_time, is_deleted
FROM agent.mining_agent_conversation
WHERE user_id = #{userId} 
    AND start_time >= #{startTime}
    AND start_time <= #{endTime}
    AND is_deleted = FALSE
ORDER BY start_time DESC

mapper.update:
UPDATE agent.mining_agent_conversation
SET status = #{status}, end_time = #{endTime}
WHERE conversation_id = #{conversationId}

UPDATE agent.mining_agent_conversation
SET last_msg_time = #{lastMsgTime}
WHERE conversation_id = #{conversationId}

UPDATE agent.mining_agent_conversation
SET is_deleted = TRUE
WHERE conversation_id = #{conversationId}
